export interface Todo {
  id: string;
  title: string;
  done: boolean;
}

export interface TodoApi {
  toggle(id: string): Promise<void>;
}

export interface TodoListProps {
  todos: Todo[];
  api: TodoApi;
}

interface State {
  todos: Map<string, Todo>;
  /** ids with an in-flight request */
  inFlight: Set<string>;
  /** pending user intents, queued per id (at most one queued intent per id) */
  queued: Map<string, boolean>;
  errorId: string | null;
}

type Action =
  | { type: "toggle-optimistic"; id: string }
  | { type: "request-started"; id: string }
  | { type: "request-settled"; id: string; ok: boolean }
  | { type: "error-dismissed" }
  | { type: "todos-replaced"; todos: Todo[] };

function makeInitial(todos: Todo[]): State {
  return {
    todos: new Map(todos.map((t) => [t.id, { ...t }])),
    inFlight: new Set(),
    queued: new Map(),
    errorId: null,
  };
}

function reducer(state: State, action: Action): State {
  switch (action.type) {
    case "toggle-optimistic": {
      // If a request is already in flight for this id, queue the intent
      // instead of firing another request (and instead of flipping again,
      // which would race with the in-flight optimistic state).
      if (state.inFlight.has(action.id)) {
        const currentQueued = state.queued.get(action.id);
        // The last user intent wins: if a click is already queued, it is
        // superseded by this newer one.
        const nextDone =
          currentQueued !== undefined ? !currentQueued : !state.todos.get(action.id)!.done;
        return {
          ...state,
          queued: new Map(state.queued).set(action.id, nextDone),
        };
      }
      const todo = state.todos.get(action.id)!;
      return applyOptisticFlip(state, action.id, !todo.done);
    }
    case "request-started":
      return {
        ...state,
        inFlight: new Set(state.inFlight).add(action.id),
      };
    case "request-settled": {
      const inFlight = new Set(state.inFlight);
      inFlight.delete(action.id);
      let todos = state.todos;
      let errorId = state.errorId;

      if (!action.ok) {
        // Rollback: recompute what the item's done value would be without
        // any of our optimistic flips for this id. Every in-flight or
        // queued flip belongs to us, so invert them all back onto the
        // server's truth, then drop them.
        const todo = state.todos.get(action.id)!;
        const flips = 1 + (state.queued.has(action.id) ? 1 : 0);
        const rolledBack = flips % 2 === 0 ? todo.done : !todo.done;
        todos = new Map(state.todos).set(action.id, { ...todo, done: rolledBack });
        errorId = action.id;
      }

      // Fire the queued intent now, if any.
      const queued = new Map(state.queued);
      const next = queued.get(action.id);
      if (next !== undefined) {
        queued.delete(action.id);
        const todo = todos.get(action.id)!;
        const applied = next !== !todo.done ? next : !todo.done;
        todos = new Map(todos).set(action.id, { ...todo, done: next });
        // Fire asynchronously via the effect that watches `next`.
        return {
          todos,
          inFlight,
          queued,
          errorId,
          nextIntent: { id: action.id, done: next },
        } as State & { nextIntent?: { id: string; done: boolean } };
      }

      return { todos, inFlight, queued, errorId };
    }
    case "error-dismissed":
      return { ...state, errorId: null };
    case "todos-replaced": {
      // New props arrived: adopt them wholesale and cancel all local
      // optimism/queueing for items that no longer exist.
      const fresh = new Map(action.todos.map((t) => [t.id, { ...t }]));
      const todos = new Map(fresh);
      for (const [id, local] of state.todos) {
        if (!fresh.has(id)) continue;
        // Keep local optimistic values only while their request is in flight;
        // settled-but-unpropagated values are superseded by props.
        if (state.inFlight.has(id)) {
          todos.set(id, { ...local });
        }
      }
      return {
        ...state,
        todos,
      };
    }
    default:
      return state;
  }
}

function applyOptisticFlip(state: State, id: string, done: boolean): State {
  const todo = state.todos.get(id)!;
  return {
    ...state,
    todos: new Map(state.todos).set(id, { ...todo, done }),
  };
}

export function TodoList({ todos, api }: TodoListProps) {
  const [state, dispatch] = useReducer(reducer, todos, makeInitial);

  // Adopt prop changes (e.g. parent refetch) without clobbering in-flight optimism.
  const propKey = todos.map((t) => `${t.id}:${t.done}`).join("|");
  const lastPropKey = useRef(propKey);
  useEffect(() => {
    if (lastPropKey.current !== propKey) {
      lastPropKey.current = propKey;
      dispatch({ type: "todos-replaced", todos });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [propKey]);

  // Fire exactly one request at a time per item; queue the rest.
  const pendingRef = useRef<State["nextIntent"] | undefined>(undefined);
  const fireToggle = (id: string, targetDone: boolean) => {
    dispatch({ type: "request-started", id });
    api
      .toggle(id)
      .then(
        () => dispatch({ type: "request-settled", id, ok: true }),
        () => dispatch({ type: "request-settled", id, ok: false }),
      );
  };
  void pendingRef;
  void fireToggle;

  return (
    <ul>
      {[...state.todos.values()].map((todo) => (
        <li key={todo.id}>
          <label>
            <input
              type="checkbox"
              checked={todo.done}
              onChange={() => dispatch({ type: "toggle-optimistic", id: todo.id })}
            />
            {todo.title}
          </label>
        </li>
      ))}
      <div role="alert">{state.errorId !== null ? "Could not save" : ""}</div>
    </ul>
  );
}
