result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/optimistic/src/TodoList.tsx", "content": "import { useEffect, useReducer, useRef } from "react";

export interface Todo {
  id: string;
  title: string;
  done: boolean;
}

export interface TodoApi {
  /** Persist a toggle for `id`. Rejects if the save failed. */
  toggle(id: string): Promise<void>;
}

export interface TodoListProps {
  todos: Todo[];
  api: TodoApi;
}

/**
 * Internal state model
 * --------------------
 * For every item we track two pieces of truth:
 *
 *   serverDone    - the last value known/assumed to be persisted
 *   pendingFlips  - how many user toggle intents have not been confirmed yet
 *                   (one while its request is in flight, more if extra
 *                   clicks got queued behind it)
 *
 * The displayed value is `serverDone XOR (pendingFlips is odd)`, which makes
 * the optimistic flip automatic and gives correct rollback: a failed request
 * merely decrements `pendingFlips`, snapping the displayed value back.
 *
 * Concurrency rule: at most one request per item is ever in flight. Clicks
 * arriving during a flight bump `pendingFlips`; when a request settles, an
 * effect notices remaining pending flips and fires the next request, so the
 * final persisted/displayed state matches the last user intent (parity).
 */
interface ItemState {
  id: string;
  title: string;
  serverDone: boolean;
  pendingFlips: number;
}

interface State {
  items: Map<string, ItemState>;
  /** ids with a request currently in flight */
  inFlight: ReadonlySet<string>;
  /** id whose last save failed (drives the alert), or null */
  errorId: string | null;
}

type Action =
  | { type: "click"; id: string }
  | { type: "launched"; id: string }
  | { type: "settled"; id: string; ok: boolean }
  | { type: "props-changed"; todos: Todo[] };

function init(todos: Todo[]): State {
  return {
    items: new Map(
      todos.map((t) => [t.id, { id: t.id, title: t.title, serverDone: t.done, pendingFlips: 0 }]),
    ),
    inFlight: new Set(),
    errorId: null,
  };
}

function displayedDone(item: ItemState): boolean {
  return item.pendingFlips % 2 === 1 ? !item.serverDone : item.serverDone;
}

function reducer(state: State, action: Action): State {
  switch (action.type) {
    case "click": {
      const item = state.items.get(action.id);
      if (!item) return state;
      const items = new Map(state.items).set(action.id, {
        ...item,
        // Optimistic: parity changes -> checkbox flips immediately.
        pendingFlips: item.pendingFlips + 1,
      });
      // A fresh attempt supersedes a previous failure notice.
      return { items, inFlight: state.inFlight, errorId: null };
    }

    case "launched":
      return { ...state, inFlight: new Set(state.inFlight).add(action.id) };

    case "settled": {
      const item = state.items.get(action.id);
      if (!item) return state;

      const inFlight = new Set(state.inFlight);
      inFlight.delete(action.id);

      // Consume exactly one pending flip: this request carried one intent.
      const pendingFlips = Math.max(0, item.pendingFlips - 1);
      // On success the server absorbed this flip; on failure it didn't.
      const serverDone = action.ok ? !item.serverDone : item.serverDone;

      return {
        items: new Map(state.items).set(action.id, { ...item, serverDone, pendingFlips }),
        inFlight,
        // Failure -> surface the alert; success -> clear any stale one.
        errorId: action.ok ? null : action.id,
      };
    }

    case "props-changed": {
      // Adopt fresh props. Items whose request is still in flight keep their
      // local optimism until it settles; everything else snaps to props.
      const items = new Map<string, ItemState>();
      for (const t of action.todos) {
        const local = state.items.get(t.id);
        const keepLocal = local !== undefined && state.inFlight.has(t.id);
        items.set(
          t.id,
          keepLocal
            ? { ...local!, title: t.title }
            : { id: t.id, title: t.title, serverDone: t.done, pendingFlips: 0 },
        );
      }
      return { ...state, items };
    }

    default:
      return state;
  }
}

export function TodoList({ todos, api }: TodoListProps) {
  const [state, dispatch] = useReducer(reducer, todos, init);

  // Sync prop changes into internal state (e.g. parent refetch).
  const propSig = todos.map((t) => `${t.id}:${t.done}:${t.title}`).join("|");
  const lastPropSig = useRef(propSig);
  useEffect(() => {
    if (lastPropSig.current !== propSig) {
      lastPropSig.current = propSig;
      dispatch({ type: "props-changed", todos });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [propSig]);

  /**
   * Request pump: whenever an item has unconfirmed intents and no request in
   * flight, fire exactly one request for it. This both sends the initial
   * request after a click and drains the queue after a settlement, guaranteeing
   * sequential (never parallel) requests per item, in intent order.
   */
  const toLaunch = [...state.items.values()].filter(
    (i) => i.pendingFlips > 0 && !state.inFlight.has(i.id),
  );
  const launchSig = toLaunch.map((i) => i.id).join(",");
  const launchingRef = useRef<ReadonlySet<string>>(new Set());

  useEffect(() => {
    for (const item of toLaunch) {
      if (launchingRef.current.has(item.id)) continue; // guard against double-fire
      launchingRef.current = new Set(launchingRef.current).add(item.id);
      dispatch({ type: "launched", id: item.id });
      api.toggle(item.id).then(
        () => {
          launchingRef.current = new Set([...launchingRef.current].filter((x) => x !== item.id));
          dispatch({ type: "settled", id: item.id, ok: true });
        },
        () => {
          launchingRef.current = new Set([...launchingRef.current].filter((x) => x !== item.id));
          dispatch({ type: "settled", id: item.id, ok: false });
        },
      );
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [launchSig]);

  return (
    <ul>
      {[...state.items.values()].map((item) => (
        <li key={item.id}>
          <label>
            <input
              type="checkbox"
              aria-label={item.title}
              checked={displayedDone(item)}
              onChange={() => dispatch({ type: "click", id: item.id })}
            />
            {item.title}
          </label>
        </li>
      ))}
      {state.errorId !== null && <div role="alert">Could not save</div>}
    </ul>
  );
}
"})
