import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { TodoList, type Todo, type TodoApi } from "./TodoList";

interface Deferred<T> {
  promise: Promise<T>;
  resolve: (value: T) => void;
  reject: (reason?: unknown) => void;
}

function deferred<T = void>(): Deferred<T> {
  let resolve!: (value: T) => void;
  let reject!: (reason?: unknown) => void;
  const promise = new Promise<T>((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

const TODOS: Todo[] = [
  { id: "a", title: "Buy milk", done: false },
  { id: "b", title: "Walk dog", done: true },
];

/** api.toggle backed by a queue of deferreds; records call order. */
function makeApi(): { api: TodoApi; calls: string[]; next: () => Deferred<void> } {
  const calls: string[] = [];
  const queue: Deferred<void>[] = [];
  return {
    calls,
    next: () => {
      const d = deferred<void>();
      queue.push(d);
      return d;
    },
    api: {
      toggle(id: string) {
        calls.push(id);
        const d = deferred<void>();
        queue.push(d);
        return d.promise;
      },
    },
  };
}

