    const user = userEvent.setup();
    const { api } = makeApi();
    render(<TodoList todos={TODOS} api={api} />);

    const box = screen.getByRole("checkbox", { name: "Buy milk" });
    await user.click(box);

    // Visible flip BEFORE resolution — no tick needed for the optimistic part.
    expect(box.checked).toBe(true);
  });

  it("keeps the flipped state when the request resolves successfully", async () => {
    const user = userEvent.setup();
    const { api, next } = makeApi();
    render(<TodoList todos={TODOS} api={api} />);

    const box = screen.getByRole("checkbox", { name: "Buy milk" });
    await user.click(box);
    expect(box.checked).toBe(true);

    await next().resolve(undefined);
    await Promise.resolve();
    expect(box.checked).toBe(true);
  });

  it("rolls back the flip and shows an alert when the request rejects", async () => {
    const user = userEvent.setup();
    const { api, next } = makeApi();
    render(<TodoList todos={TODOS} api={api} />);

    const box = screen.getByRole("checkbox", { name: "Buy milk" });
    await user.click(box);
